 882	  /** Opaque bidirectional JDBC traffic only; no bodies, credentials or authority are recorded. */
 883	  private static final class PrivatePgRoute implements AutoCloseable {
 884	    private final InetSocketAddress target;
 885	    private final ExecutorService bridges = Executors.newVirtualThreadPerTaskExecutor();
 886	    private final Set<java.net.Socket> sockets = ConcurrentHashMap.newKeySet();
 887	    private volatile java.net.ServerSocket listener;
 888	    private int privatePort;
 889	    private boolean closed;
 890	
 891	    PrivatePgRoute(String host, int port) throws IOException {
 892	      target = new InetSocketAddress(host, port);
 893	      reopen();
 894	    }
 895	    synchronized int port() { return privatePort; }
 896	    synchronized void reopen() throws IOException {
 897	      if (closed) { throw new IOException("Case-owned PG route is closed"); }
 898	      if (listener != null && !listener.isClosed()) { return; }
 899	      var server = new java.net.ServerSocket();
 900	      server.setReuseAddress(true);
 901	      server.bind(new InetSocketAddress("127.0.0.1", privatePort));
 902	      privatePort = server.getLocalPort();
 903	      listener = server;
 904	      bridges.submit(() -> accept(server));
 905	    }
 906	    private void accept(java.net.ServerSocket server) {
 907	      while (!server.isClosed()) {
 908	        java.net.Socket application = null;
 909	        java.net.Socket database = null;
 910	        try {
 911	          application = server.accept();
 912	          sockets.add(application);
 913	          if (server.isClosed()) { closeSocket(application); return; }
 914	          database = new java.net.Socket();
 915	          sockets.add(database);
 916	          database.connect(target, 3000);
 917	          if (server.isClosed()) { closeSocket(application); closeSocket(database); return; }
 918	          java.net.Socket app = application, pg = database;
 919	          bridges.submit(() -> transfer(app, pg));
 920	          bridges.submit(() -> transfer(pg, app));
 921	        } catch (IOException | java.util.concurrent.RejectedExecutionException failure) {
 922	          closeSocket(application); closeSocket(database);
 923	          if (server.isClosed()) { return; }
 924	        }
 925	      }
 926	    }
 927	    private void transfer(java.net.Socket from, java.net.Socket to) {
 928	      byte[] bytes = new byte[8192];
 929	      try {
 930	        int count;
 931	        while ((count = from.getInputStream().read(bytes)) != -1) {
 932	          to.getOutputStream().write(bytes, 0, count);
 933	          to.getOutputStream().flush();
 934	        }
 935	      } catch (IOException disconnected) {
 936	        // JDBC completion and the explicit private route cut close both opaque sides.
 937	      } finally {
 938	        Arrays.fill(bytes, (byte) 0);
 939	        closeSocket(from); closeSocket(to);
 940	      }
 941	    }
 942	    private void closeSocket(java.net.Socket socket) {
 943	      if (socket == null) { return; }
 944	      sockets.remove(socket);
 945	      try { socket.close(); } catch (IOException ignored) { /* Already disconnected. */ }
 946	    }
 947	    synchronized void unavailable() throws IOException {
 948	      if (listener != null) { listener.close(); listener = null; }
 949	      for (var socket : sockets.toArray(java.net.Socket[]::new)) { closeSocket(socket); }
 950	    }
 951	    @Override public void close() throws Exception {
 952	      synchronized (this) { closed = true; unavailable(); }
 953	      bridges.shutdownNow();
 954	      assertThat(bridges.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
 955	      assertThat(sockets).isEmpty();
 956	    }
 957	  }
