  private static GuidedSessionService service(
      GuidedSessionRepository repository,
      GuidedMaterializationService materialization,
      FixtureAccess access,
      int seconds) {
    var service =
        new GuidedSessionService(
            repository,
            C,
            access,
            new GuidedSessionProperties(true, Map.of("maxSessionSeconds", seconds)),
            Clock.systemUTC());
    service.installBridge(
        materialization,
        new GuidedPreparationStore(actualJdbc, C),
        new GuidedBindingStore(actualJdbc, C, materialization),
        new GuidedAssignmentStore(actualJdbc, C));
    service.installSecretAudit(
        new SecretAuditLifecycle(actualJdbc, new SecretUseAuditRecorder(actualJdbc)));
    return service;
  }

