  private static GuidedRunnerClient client() {
    return new GuidedRunnerClient(
        URI.create("https://localhost:" + RELAY.getAddress().getPort()),
        TLS,
        () -> token("backend-controller", "controller-1", "studio-guided-runner"),
        C);
