+          to.getOutputStream().write(bytes, 0, count);
+          to.getOutputStream().flush();
+        }
+      } catch (IOException disconnected) {
+        // JDBC completion and the explicit private route cut close both opaque sides.
+      } finally {
+        Arrays.fill(bytes, (byte) 0);
+        closeSocket(from); closeSocket(to);
+      }
+    }
+    private void closeSocket(java.net.Socket socket) {
+      if (socket == null) { return; }
+      sockets.remove(socket);
+      try { socket.close(); } catch (IOException ignored) { /* Already disconnected. */ }
+    }
+    synchronized void unavailable() throws IOException {
+      if (listener != null) { listener.close(); listener = null; }
+      for (var socket : sockets.toArray(java.net.Socket[]::new)) { closeSocket(socket); }
+    }
+    @Override public void close() throws Exception {
+      synchronized (this) { closed = true; unavailable(); }
+      bridges.shutdownNow();
+      assertThat(bridges.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
+      assertThat(sockets).isEmpty();
+    }
